'use strict';

// effectors/launch-policy.js — what may launch_app start WITHOUT a per-call
// approval? (2026-09-29 audit, B2a.) Pure: no pc-child, no fs.
//
// It classifies a RESOLVED target — the record pc-child's resolve_app returns
// ({ resolved, kind, identity, executable, appId, fixedArgs }) — never the name
// the model typed. A name decides nothing: measured 2026-09-29 on the operator's
// machine, "cmd" resolves (Start Apps, substring) to "Git CMD", whose AppID is an
// opaque Microsoft.AutoGenerated.{GUID}; "powershell" resolves through App Paths;
// "terminal" to the Windows Terminal package. Registration in App Paths or Start
// Apps is RESOLUTION, not safety.
//
// Three answers:
//   'ordinary'           — on the reviewed allowlist below: launches as before.
//   'execution-surface'  — a shell, terminal, script host, console, control-panel
//                          module or anything else that runs arbitrary input:
//                          needs the operator's per-call approval.
//   'unknown'            — anything not on either list (an AutoGenerated AppID, an
//                          IDE, an installer): ALSO needs approval. The default
//                          for an unclassified identity is to ask (operator
//                          decision recorded in the remediation plan).
// And 'unresolved' for a record that names nothing — which fails even approved.
//
// The allowlist is deliberately short and reviewable. Adding an app is a code
// change with a test, not a setting: a setting would be one more thing a
// model-driven settings write could widen.

// Executable basenames (lowercase, without .exe) of ordinary applications.
const ORDINARY_EXECUTABLES = Object.freeze(new Set([
  'notepad', 'mspaint', 'calc', 'calculatorapp', 'slack', 'teams', 'ms-teams', 'chrome', 'msedge',
  'firefox', 'brave', 'opera', 'spotify', 'discord', 'whatsapp', 'telegram', 'outlook', 'olk',
  'winword', 'excel', 'powerpnt', 'onenote', 'vlc', 'zoom', 'obs64',
]));

// Start Apps package families (the AppID up to "_", or the whole AUMID for a
// Win32 registration) of ordinary applications.
const ORDINARY_PACKAGES = Object.freeze(new Set([
  'microsoft.windowsnotepad', 'microsoft.windowscalculator', 'microsoft.paint', 'msteams',
  '5319275a.whatsappdesktop', 'spotifyab.spotifymusic', 'microsoft.outlookforwindows',
  'microsoft.screensketch', 'microsoft.windows.photos', 'microsoft.windowscamera',
  'microsoft.windowsalarms', 'telegrammessengerllp.telegramdesktop', 'microsoft.windows.explorer',
  'msedge', 'chrome', 'microsoft.zunemusic', 'microsoft.windowssoundrecorder',
  'microsoft.microsoftstickynotes', 'microsoft.todos', 'microsoft.bingweather',
]));

// Executables that run arbitrary input. Named so the approval prompt can say
// WHY; anything unlisted still needs approval as 'unknown'.
const EXECUTION_SURFACE_EXECUTABLES = Object.freeze(new Set([
  'cmd', 'powershell', 'powershell_ise', 'pwsh', 'wt', 'windowsterminal', 'conhost', 'openconsole',
  'bash', 'sh', 'wsl', 'wslhost', 'ubuntu', 'debian', 'kali', 'python', 'pythonw', 'python3', 'py', 'pyw',
  'node', 'deno', 'bun', 'wscript', 'cscript', 'mshta', 'rundll32', 'regsvr32', 'msiexec', 'mmc',
  'control', 'regedit', 'reg', 'sc', 'schtasks', 'certutil', 'bitsadmin', 'java', 'javaw', 'ruby',
  'perl', 'php', 'git-bash', 'git-cmd', 'mintty', 'msbuild', 'installutil', 'forfiles', 'cmstp',
  'wmic', 'netsh', 'diskpart', 'bcdedit', 'vssadmin', 'msdt', 'hh',
]));
const EXECUTION_SURFACE_PACKAGES = Object.freeze(new Set([
  'microsoft.windowsterminal', 'microsoft.windowsterminalpreview', 'microsoft.powershell',
  'microsoft.powershellpreview', 'windows.immersivecontrolpanel', 'microsoft.windows.controlpanel',
  'microsoft.windowssubsystemforlinux', 'microsoftcorporationii.windowssubsystemforlinux',
]));
const EXECUTION_SURFACE_PACKAGE_PREFIXES = Object.freeze(['canonicalgrouplimited.', 'pythonsoftwarefoundation.',
  'thedebianproject.', 'kalilinux.', 'suse.']);
// Control-panel modules and management consoles, by extension.
const EXECUTION_SURFACE_EXTENSIONS = /\.(cpl|msc|bat|cmd|ps1|vbs|vbe|js|jse|wsf|wsh|hta|scr|lnk|reg)$/i;

function basenameOf(p) {
  const s = String(p || '').replace(/\\/g, '/');
  return s.slice(s.lastIndexOf('/') + 1).toLowerCase();
}
function stem(p) { return basenameOf(p).replace(/\.exe$/, ''); }

// A Start Apps AppID is either a package AUMID ("Family_publisher!App"), a
// known-folder path ("{GUID}\cmd.exe" — classified by its executable), or an
// opaque Microsoft.AutoGenerated.{GUID} that names nothing reviewable.
function packageOf(appId) {
  const s = String(appId || '').toLowerCase();
  const bang = s.indexOf('!');
  const head = bang === -1 ? s : s.slice(0, bang);
  const us = head.indexOf('_');
  return us === -1 ? head : head.slice(0, us);
}

function classifyLaunchTarget(target) {
  if (!target || target.resolved !== true) return { kind: 'unresolved', reason: 'no application matches that name' };
  if (target.kind === 'spotify') return { kind: 'ordinary', reason: 'spotify' };
  const fixed = Array.isArray(target.fixedArgs) ? target.fixedArgs : [];
  // Fixed args come only from pc-child's own KnownApps table (Discord's
  // --processStart Discord.exe). Arguments from anywhere else make a launch an
  // execution surface by definition.
  if (fixed.length && target.kind !== 'known') return { kind: 'execution-surface', reason: 'arguments on a non-table launch' };
  // A KnownApps record is an entry in pc-child's own reviewed table, keyed by the
  // app's name; its executable may be a bootstrapper (Discord's Update.exe), so it
  // is classified by that name, and pc-child re-checks the path against the table.
  if (target.kind === 'known') {
    const id = String(target.identity || '').toLowerCase();
    return ORDINARY_EXECUTABLES.has(id) ? { kind: 'ordinary', reason: id } : { kind: 'unknown', reason: id };
  }
  if (target.executable) {
    const exe = String(target.executable);
    if (EXECUTION_SURFACE_EXTENSIONS.test(exe)) return { kind: 'execution-surface', reason: basenameOf(exe) };
    const name = stem(exe);
    if (EXECUTION_SURFACE_EXECUTABLES.has(name)) return { kind: 'execution-surface', reason: name };
    if (ORDINARY_EXECUTABLES.has(name)) return { kind: 'ordinary', reason: name };
    return { kind: 'unknown', reason: name };
  }
  if (target.appId) {
    const id = String(target.appId);
    if (/[\\/]/.test(id)) return classifyLaunchTarget({ resolved: true, kind: 'app-paths', executable: id });
    if (/^microsoft\.autogenerated\./i.test(id)) return { kind: 'unknown', reason: 'an auto-generated Start menu entry names no reviewable app' };
    const pkg = packageOf(id);
    if (EXECUTION_SURFACE_PACKAGES.has(pkg) || EXECUTION_SURFACE_PACKAGE_PREFIXES.some((p) => pkg.startsWith(p))) {
      return { kind: 'execution-surface', reason: pkg };
    }
    if (ORDINARY_PACKAGES.has(pkg)) return { kind: 'ordinary', reason: pkg };
    return { kind: 'unknown', reason: pkg };
  }
  return { kind: 'unknown', reason: 'the resolved target names no executable or app id' };
}

// What the operator is shown when asked to approve: the resolved thing, not the
// name that was typed.
function describeLaunchTarget(target) {
  if (!target || target.resolved !== true) return 'nothing (unresolved)';
  const what = target.startName || target.identity || '';
  const where = target.executable || target.appId || target.kind;
  const args = Array.isArray(target.fixedArgs) && target.fixedArgs.length ? ` ${target.fixedArgs.join(' ')}` : '';
  return `${what ? what + ' — ' : ''}${where}${args}`;
}

module.exports = {
  classifyLaunchTarget,
  describeLaunchTarget,
  ORDINARY_EXECUTABLES,
  ORDINARY_PACKAGES,
  EXECUTION_SURFACE_EXECUTABLES,
  EXECUTION_SURFACE_PACKAGES,
};
